export class UsersService {
  /**
   * Unsubscribe Watchlist Digest
   * One-click unsubscribe from watchlist digest emails, linked from the email itself.
   *
   * No authentication — the signed token in the link is what proves the
   * request is for that specific user's account.
   * @param data The data for the request.
   * @param data.token
   * @returns string Successful Response
   * @throws ApiError
   */
  public static unsubscribeWatchlistDigest(
    data: UsersUnsubscribeWatchlistDigestData,
  ): CancelablePromise<UsersUnsubscribeWatchlistDigestResponse> {
    return __request(OpenAPI, {
      method: "GET",
      url: "/api/v1/users/unsubscribe-watchlist-digest",
      query: {
        token: data.token,
      },
      errors: {
        422: "Validation Error",
      },
    })
  }

  /**
   * Verify Email
   * Confirm an email address from the link mailed at registration.
   *
   * No authentication — the signed token in the link is what proves the request
   * came from someone reading that mailbox, which is the whole point of it.
   * Already-verified accounts are answered the same way as a fresh confirmation:
   * a second click on the same link is a normal thing to do, and it has the
   * outcome the user wanted either way.
   * @param data The data for the request.
   * @param data.token
   * @returns string Successful Response
   * @throws ApiError
   */
  public static verifyEmail(
    data: UsersVerifyEmailData,
  ): CancelablePromise<UsersVerifyEmailResponse> {
    return __request(OpenAPI, {
      method: "GET",
      url: "/api/v1/users/verify-email",
      query: {
        token: data.token,
      },
      errors: {
        422: "Validation Error",
      },
    })
  }

  /**
   * Search Users
   * @param data The data for the request.
   * @param data.query
   * @param data.offset
   * @param data.limit
   * @returns UserWithFriendStatus Successful Response
   * @throws ApiError
   */
  public static searchUsers(
    data: UsersSearchUsersData,
  ): CancelablePromise<UsersSearchUsersResponse> {
    return __request(OpenAPI, {
      method: "GET",
      url: "/api/v1/users/search",
      query: {
        query: data.query,
        offset: data.offset,
        limit: data.limit,
      },
      errors: {
        422: "Validation Error",
      },
    })
  }

  /**
   * Register User
   * @param data The data for the request.
   * @param data.requestBody
   * @returns UserPublic Successful Response
   * @throws ApiError
   */
  public static registerUser(
    data: UsersRegisterUserData,
  ): CancelablePromise<UsersRegisterUserResponse> {
    return __request(OpenAPI, {
      method: "POST",
      url: "/api/v1/users/signup",
      body: data.requestBody,
      mediaType: "application/json",
      errors: {
        422: "Validation Error",
      },
    })
  }

  /**
   * Get User Friend Status
   * A single user's friendship/request status relative to the current user.
   *
   * Polled by e.g. a showtime's "Invited" list so a status change made
   * elsewhere (the other side accepted/declined) is noticed without
   * refetching the whole showtime.
   * @param data The data for the request.
   * @param data.userId
   * @returns UserWithFriendStatus Successful Response
   * @throws ApiError
   */
  public static getUserFriendStatus(
    data: UsersGetUserFriendStatusData,
  ): CancelablePromise<UsersGetUserFriendStatusResponse> {
    return __request(OpenAPI, {
      method: "GET",
      url: "/api/v1/users/{user_id}/friend-status",
      path: {
        user_id: data.userId,
      },
      errors: {
        422: "Validation Error",
      },
    })
  }

  /**
   * Block User
   * Block a user: no contact in either direction from here on.
   *
   * Tears down the friendship, any pending request and every standing invite
   * between the two accounts — see services/moderation.py for why a block has to
   * be a teardown rather than a flag.
   * @param data The data for the request.
   * @param data.userId
   * @returns Message Successful Response
   * @throws ApiError
   */
  public static blockUser(
    data: UsersBlockUserData,
  ): CancelablePromise<UsersBlockUserResponse> {
    return __request(OpenAPI, {
      method: "POST",
      url: "/api/v1/users/{user_id}/block",
      path: {
        user_id: data.userId,
      },
      errors: {
        422: "Validation Error",
      },
    })
  }

  /**
   * Unblock User
   * Lift a block. Does not restore the friendship or invites it removed.
   * @param data The data for the request.
   * @param data.userId
   * @returns Message Successful Response
   * @throws ApiError
   */
  public static unblockUser(
    data: UsersUnblockUserData,
  ): CancelablePromise<UsersUnblockUserResponse> {
    return __request(OpenAPI, {
      method: "DELETE",
      url: "/api/v1/users/{user_id}/block",
      path: {
        user_id: data.userId,
      },
      errors: {
        422: "Validation Error",
      },
    })
  }

  /**
   * Report User
   * Report a user for moderation, and block them unless asked not to.
   *
   * Mails the report to the operator as well as recording it, so guideline 1.2's
   * "timely responses to concerns" has something to respond from.
   * @param data The data for the request.
   * @param data.userId
   * @param data.requestBody
   * @returns Message Successful Response
   * @throws ApiError
   */
  public static reportUser(
    data: UsersReportUserData,
  ): CancelablePromise<UsersReportUserResponse> {
    return __request(OpenAPI, {
      method: "POST",
      url: "/api/v1/users/{user_id}/report",
      path: {
        user_id: data.userId,
      },
      body: data.requestBody,
      mediaType: "application/json",
      errors: {
        422: "Validation Error",
      },
    })
  }

  /**
   * Get User
   * Get a user by their ID.
   * @param data The data for the request.
   * @param data.userId
   * @returns UserPublic Successful Response
   * @throws ApiError
   */
  public static getUser(
    data: UsersGetUserData,
  ): CancelablePromise<UsersGetUserResponse> {
    return __request(OpenAPI, {
      method: "GET",
      url: "/api/v1/users/{user_id}",
      path: {
        user_id: data.userId,
      },
      errors: {
        422: "Validation Error",
      },
    })
  }

  /**
   * Get User Selected Showtimes
   * @param data The data for the request.
   * @param data.userId
   * @param data.limit
   * @param data.offset
   * @param data.query
   * @param data.searchField Which attribute `query` is matched against
   * @param data.snapshotTime Only show showtimes after this moment
   * @param data.watchlistOnly
   * @param data.watchlistExclude
   * @param data.hideWatched
   * @param data.watchedOnly
   * @param data.selectedCinemaIds Filter showtimes to only these cinema IDs
   * @param data.days
   * @param data.timeRanges
   * @param data.timesOfDay Preset time windows (MORNING/AFTERNOON/EVENING/NIGHT)
   * @param data.selectedStatuses Filter by selection statuses (GOING/INTERESTED)
   * @param data.selectedListIds Only show movies on any of these Letterboxd lists
   * @param data.excludeListIds Hide movies on any of these Letterboxd lists
   * @param data.runtimeMin Minimum movie runtime in minutes
   * @param data.runtimeMax Maximum movie runtime in minutes
   * @param data.selectedLanguages Keep movies whose main spoken language is one of these, and only showtimes with matching subtitles
   * @returns ShowtimePublic Successful Response
   * @throws ApiError
   */
  public static getUserSelectedShowtimes(
    data: UsersGetUserSelectedShowtimesData,
  ): CancelablePromise<UsersGetUserSelectedShowtimesResponse> {
    return __request(OpenAPI, {
      method: "GET",
      url: "/api/v1/users/{user_id}/showtimes",
      path: {
        user_id: data.userId,
      },
      query: {
        limit: data.limit,
        offset: data.offset,
        query: data.query,
        search_field: data.searchField,
        snapshot_time: data.snapshotTime,
        watchlist_only: data.watchlistOnly,
        watchlist_exclude: data.watchlistExclude,
        hide_watched: data.hideWatched,
        watched_only: data.watchedOnly,
        selected_cinema_ids: data.selectedCinemaIds,
        days: data.days,
        time_ranges: data.timeRanges,
        times_of_day: data.timesOfDay,
        selected_statuses: data.selectedStatuses,
        selected_list_ids: data.selectedListIds,
        exclude_list_ids: data.excludeListIds,
        runtime_min: data.runtimeMin,
        runtime_max: data.runtimeMax,
        selected_languages: data.selectedLanguages,
      },
      errors: {
        422: "Validation Error",
      },
    })
  }
}

